class Solution:
    def maxPoints(self, technique1: list[int], technique2: list[int], k: int) -> int:
        total = 0
        losses = []
        for a, b in zip(technique1, technique2):
            total += max(a, b)
            if b > a:
                losses.append(b - a)
        losses.sort()
        return total - sum(losses[:k])

