class Solution {
public:
    long long maxPoints(vector<int>& technique1, vector<int>& technique2, int k) {
        long long total = 0;
        vector<int> losses;
        for (size_t i = 0; i < technique1.size(); i++) {
            total += max(technique1[i], technique2[i]);
            if (technique2[i] > technique1[i])
                losses.push_back(technique2[i] - technique1[i]);
        }
        sort(losses.begin(), losses.end());
        for (int i = 0; i < k && i < (int)losses.size(); i++) total -= losses[i];
        return total;
    }
};

