import heapq
class Solution:
    def maxPoints(self, technique1: list[int], technique2: list[int], k: int) -> int:
        total = 0
        heap = []
        s = 0
        for a, b in zip(technique1, technique2):
            total += max(a, b)
            if b > a:
                heapq.heappush(heap, -(b - a))
                s += b - a
                if len(heap) > k:
                    s += heapq.heappop(heap)
        return total - s

