class Solution {
public:
    long long maxPoints(vector<int>& t1, vector<int>& t2, int k) {
        long long total = 0, s = 0;
        priority_queue<int> pq;
        for (size_t i = 0; i < t1.size(); i++) {
            total += max(t1[i], t2[i]);
            if (t2[i] > t1[i]) {
                pq.push(t2[i] - t1[i]); s += t2[i] - t1[i];
                if ((int)pq.size() > k) { s -= pq.top(); pq.pop(); }
            }
        }
        return total - s;
    }
};

