class Solution {
    public long maxPoints(int[] t1, int[] t2, int k) {
        long total = 0, s = 0;
        PriorityQueue<Integer> pq = new PriorityQueue<>(java.util.Collections.reverseOrder());
        for (int i = 0; i < t1.length; i++) {
            total += Math.max(t1[i], t2[i]);
            if (t2[i] > t1[i]) {
                pq.offer(t2[i] - t1[i]); s += t2[i] - t1[i];
                if (pq.size() > k) s -= pq.poll();
            }
        }
        return total - s;
    }
}

